## Comprehensive Next.js E-Commerce App Analysis

### 1. PROJECT STRUCTURE AND OVERVIEW

```
/app (root directory)
├── public/                          # Static assets
│   └── fonts/
│       └── custom.woff2            # Custom font file
├── src/
│   ├── app/                        # Next.js App Router
│   │   ├── layout.tsx              # Root layout component
│   │   ├── page.tsx                # Home page
│   │   └── globals.css             # Global styles with Tailwind
│   ├── components/                 # Reusable components
│   │   ├── Banner.tsx              # Promo banner
│   │   ├── LateBanner.tsx           # Secondary banner
│   │   ├── ProductCard.tsx          # Individual product card
│   │   ├── ProductList.tsx          # Product grid container
│   │   ├── ProductSkeleton.tsx      # Loading skeleton
│   │   ├── ResultsBar.tsx           # Pagination and results info
│   │   ├── SidePane.tsx             # Left sidebar navigation
│   │   └── ThemeProvider.tsx        # Dark/Light theme provider
│   └── data/
│       └── products.json            # Sample product data (200 products)
├── node_modules/                   # Dependencies
├── output/                          # Build output directory
├── package.json                    # Project metadata and dependencies
├── package-lock.json               # Locked dependency versions
├── tsconfig.json                   # TypeScript configuration
├── next.config.js                  # Next.js configuration
├── postcss.config.js               # PostCSS configuration
├── next-env.d.ts                   # Next.js TypeScript definitions
└── .gitignore (implied)            # Git ignore rules
```

---

### 2. FRAMEWORK VERSIONS

**package.json dependencies:**
- **Next.js**: 14.0.4 (App Router-based)
- **React**: 18.2.0
- **React DOM**: 18.2.0

**Dev Dependencies:**
- TypeScript: 5.3.3
- Tailwind CSS: 4.1.18
- Tailwind CSS PostCSS plugin: 4.1.18
- PostCSS: 8.5.6
- Autoprefixer: 10.4.23
- Playwright: 1.49.1 (for testing)
- @types/node: 20.10.0
- @types/react: 18.2.0

---

### 3. PAGE COMPONENTS AND LAYOUTS

#### **Layout Files:**

**File**: `/app/src/app/layout.tsx`
- **Type**: Root layout (Server Component)
- **Purpose**: Wraps entire application
- **Content**:
  - Imports Metadata type from 'next'
  - Sets page title: "Modern Marketplace"
  - Sets page description: "Your one-stop shop for everything"
  - Wraps children with ThemeProvider for dark/light mode
  - HTML lang="en" and body structure

```typescript
import type { Metadata } from 'next';
import { ThemeProvider } from '@/components/ThemeProvider';
import './globals.css';

export const metadata: Metadata = {
  title: 'Modern Marketplace',
  description: 'Your one-stop shop for everything',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>
        <ThemeProvider>
          {children}
        </ThemeProvider>
      </body>
    </html>
  );
}
```

#### **Page Files:**

**File**: `/app/src/app/page.tsx`
- **Type**: Client Component (marked with 'use client')
- **Purpose**: Home page displaying marketplace
- **Content**:
  - Header with theme toggle button
  - Banner component (promo)
  - LateBanner component (secondary promo)
  - Left sidebar (SidePane) with categories/filters
  - Main content area with:
    - ResultsBar (pagination and product count)
    - ProductList (grid of products)
  - Manages page state and total products count
  - Integrates ThemeProvider's useTheme hook

```typescript
'use client';

import { useState } from 'react';
import { useTheme } from '@/components/ThemeProvider';
import Banner from '@/components/Banner';
import ProductList from '@/components/ProductList';
import LateBanner from '@/components/LateBanner';
import SidePane from '@/components/SidePane';
import ResultsBar from '@/components/ResultsBar';

export default function Home() {
  const { theme, toggleTheme } = useTheme();
  const [page, setPage] = useState(1);
  const [totalProducts, setTotalProducts] = useState(0);

  return (
    <main>
      <header className="flex justify-between items-center p-5 border-b" style={{ borderColor: 'var(--border-color)' }}>
        <h1 className="text-2xl">Modern Marketplace</h1>
        <button
          data-testid="theme-toggle"
          className="px-4 py-2 border-none rounded bg-[#0070f3] text-white cursor-pointer"
          onClick={toggleTheme}
        >
          {theme === 'light' ? 'Dark Mode' : 'Light Mode'}
        </button>
      </header>
      <Banner />
      <LateBanner />
      <div className="flex">
        <SidePane />
        <div data-testid="main-content" className="flex-1">
          <ResultsBar
            page={page}
            totalProducts={totalProducts}
            onPageChange={setPage}
          />
          <ProductList
            page={page}
            onProductsLoaded={setTotalProducts}
          />
        </div>
      </div>
    </main>
  );
}
```

---

### 4. REUSABLE COMPONENTS

#### **1. Banner.tsx** (`/app/src/components/Banner.tsx`)
- **Type**: Client Component
- **Purpose**: Display promotional banner
- **Features**:
  - Fetches promo text from `/api/banner` endpoint
  - Uses useEffect for client-side data loading
  - Conditionally renders (returns null if no promo)
  - Blue background (#0070f3) with white text
  - Test ID: "promo-banner"

```typescript
'use client';

import { useState, useEffect } from 'react';

const API_URL = '';

export default function Banner() {
  const [promo, setPromo] = useState<string>('');

  useEffect(() => {
    fetch(`${API_URL}/api/banner`)
      .then(r => r.json())
      .then(data => setPromo(data.text));
  }, []);

  if (!promo) return null;

  return (
    <div
      data-testid="promo-banner"
      className="bg-[#0070f3] text-white py-24 px-4 text-center font-bold text-2xl"
    >
      {promo}
    </div>
  );
}
```

#### **2. LateBanner.tsx** (`/app/src/components/LateBanner.tsx`)
- **Type**: Client Component
- **Purpose**: Display secondary banner
- **Features**:
  - Fetches text from `/api/late-banner` endpoint
  - Orange background (#ff6b35) with white text
  - Similar structure to Banner component
  - Test ID: "late-banner"

```typescript
'use client';

import { useState, useEffect } from 'react';

const API_URL = '';

export default function LateBanner() {
  const [text, setText] = useState<string>('');

  useEffect(() => {
    fetch(`${API_URL}/api/late-banner`)
      .then(r => r.json())
      .then(data => setText(data.text));
  }, []);

  if (!text) return null;

  return (
    <div
      data-testid="late-banner"
      className="bg-[#ff6b35] text-white py-32 px-4 text-center font-bold text-[28px]"
    >
      {text}
    </div>
