'use client';

import { useState, useEffect } from 'react';

const API_URL = '';

export default function LateBanner() {
  const [text, setText] = useState<string>('');

  useEffect(() => {
    fetch(`${API_URL}/api/late-banner`)
      .then(r => r.json())
      .then(data => setText(data.text));
  }, []);

  if (!text) {
    return (
      <div
        data-testid="late-banner"
        className="bg-[#ff6b35] py-32 px-4"
      >
        <div className="h-8 w-1/3 mx-auto bg-white/20 rounded animate-pulse" />
      </div>
    );
  }

  return (
    <div
      data-testid="late-banner"
      className="bg-[#ff6b35] text-white py-32 px-4 text-center font-bold text-[28px]"
    >
      {text}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';

const API_URL = '';

export default function SidePane() {
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    fetch(`${API_URL}/api/side-pane`)
      .then(r => r.json())
